class Agent:
    def __init__(self, name, parent=None):
        self.name = name
        self.parent = parent

    def handle(self, task):
        if task == "hard":
            return self.parent.handle(task)
        if not self.parent:
            return "unhandled"
        return self.parent.handle(task)

阅读下面的伪代码（描述的是长期记忆写入流程），回答问题：

```
def remember(user_id, utterance, memory_store):
    info = extract(utterance)          # 从用户话语抽取关键信息
    if info is None:
        return
    existing = memory_store.query(user_id, info.key)
    if existing:
        memory_store.update(existing.id, value=info.value, ts=now())
    else:
        memory_store.insert(user_id, info.key, info.value, ts=now())
```

